import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Texture,
  Vector3,
  Euler,
  Matrix4,
  Color,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  texture,
  uv,
  mul,
  add,
  sin,
  abs,
  vec2,
  vec3,
  color,
  normalize,
  normalWorld,
  positionWorld,
  positionLocal,
  viewDirection,
  madd,
  mix,
  builtin,
} from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { fontAtlas } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{ x: number, y: number, z: number }} position
 * @property {{ x: number, y: number, z: number }} rotation
 * @property {{ x: number, y: number, z: number }} scale
 * @property {string} imageUrl
 * @property {string} depthMapUrl
 * @property {Array<{ name: string, params: any }>} cinematicPrimitives
 * @property {any} textContent
 * @property {Array<any>} neighbors
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Promise<Texture>} textureLoader
 * @property {(url:string)=>Promise<any>} glbLoader
 * @property {{[key:string]:(target:any, params:any)=>void}} primitives
 * @property {{emit:(event:string)=>void}} emit
 * @property {{fontAtlas:any}} fontAtlas
 */

/**
 * Create the ornamental divider node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Geometry
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Load textures (synchronously via cached loaders)
  /** @type {Texture} */
  const colorTex = ctx.textureLoader(config.imageUrl);
  /** @type {Texture} */
  const depthTex = ctx.textureLoader(config.depthMapUrl);

  // Material built with TSL nodes
  const mat = new MeshStandardNodeMaterial();

  // Base color from texture
  mat.colorNode = texture(colorTex);

  // Displacement using depth map (scaled to subtle effect)
  const dispScale = 0.07; // subtle depth
  mat.displacementNode = mul(texture(depthTex), dispScale);

  // Optional: enhance with normal derived from depth for better lighting
  const normalFromDepth = builtin('NormalmapNode', {
    map: depthTex,
    scale: dispScale,
  });
  mat.normalNode = normalFromDepth;

  // Create mesh
  const mesh = new Mesh(geometry, mat);
  mesh.name = 'ornamental-divider';

  // Apply transform from config
  mesh.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  mesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  mesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // Apply cinematic primitives (parallax scroll if not already present)
  const hasParallax = (config.cinematicPrimitives || []).some(
    (p) => p.name === 'parallax-scroll'
  );
  if (!hasParallax && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](mesh, {});
  }

  // Interaction timelines
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    mesh.position,
    {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  // Store cleanup disposables
  const disposables = [];

  // Handlers container
  mesh.userData.handlers = {};

  // Hover handling (enter/leave)
  mesh.userData.handlers.pointerover = () => {
    hoverTimeline.play();
  };
  mesh.userData.handlers.pointerout = () => {
    hoverTimeline.reverse();
  };

  // Click handling
  mesh.userData.handlers.click = () => {
    if (ctx.emit) ctx.emit('hub-features.select');
  };

  // Cleanup function
  mesh.userData.cleanup = () => {
    geometry.dispose();
    mat.dispose();
    if (colorTex) colorTex.dispose();
    if (depthTex) depthTex.dispose();
    hoverTimeline.kill();
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
  };

  // Return as a generic Object3D container (in case siblings need grouping)
  const container = new Object3D();
  container.add(mesh);
  container.userData = mesh.userData; // expose handlers and cleanup at root

  return container;
}
